  private TreeNode go(TreeNode n, int p, int q) {
    if (n == null || n.val == p || n.val == q) return n;
    TreeNode l = go(n.left, p, q), r = go(n.right, p, q);
    if (l != null && r != null) return n;
    return l != null ? l : r;
  }
}

