import java.util.*;

class Solution {
  public String serialize(TreeNode root) {
    StringBuilder sb = new StringBuilder();
    pre(root, sb);
    return sb.toString();
  }
  private void pre(TreeNode n, StringBuilder sb) {
    if (sb.length() > 0) sb.append(',');
    if (n == null) { sb.append('#'); return; }
    sb.append(n.val);
    pre(n.left, sb); pre(n.right, sb);
  }
  public TreeNode deserialize(String data) {
    Deque<String> q = new ArrayDeque<>(Arrays.asList(data.split(",")));
    return read(q);
  }
  private TreeNode read(Deque<String> q) {
    String s = q.poll();
    if (s == null || s.equals("#")) return null;
    TreeNode n = new TreeNode(Integer.parseInt(s));
    n.left = read(q); n.right = read(q);
    return n;
  }
}

