function myAtoi(s) {
  const MAX = 2147483647, MIN = -2147483648;
  let i = 0, sign = 1, n = 0;
  while (i < s.length && s[i] === ' ') i++;
  if (s[i] === '+' || s[i] === '-') { if (s[i] === '-') sign = -1; i++; }
  while (i < s.length && s[i] >= '0' && s[i] <= '9') {
    n = n * 10 + (s.charCodeAt(i) - 48);
    if (sign * n > MAX) return MAX;
    if (sign * n < MIN) return MIN;
    i++;
  }
  return sign * n || 0;
}

